"""Eighteen attention lenses; relevance scores are not truth or bias diagnoses."""
LENS_DEFINITIONS = {'deductive': 'Test whether conclusions follow from premises; expose invalid or missing premises.', 'inductive': 'Assess generalization, sampling, representativeness, and counterexamples.', 'abductive': 'Compare plausible explanations and derive discriminating tests.', 'analogical': 'Use structural analogies while identifying material disanalogies.', 'causal': 'Separate correlation from causation; inspect mechanisms, confounders, and interventions.', 'probabilistic': 'Use base rates, uncertainty ranges, Bayesian updates, and expected values where useful.', 'counterfactual': 'Ask how outcomes change under explicit interventions or alternative histories.', 'systems': 'Map actors, incentives, dependencies, feedback loops, delays, and second-order effects.', 'temporal': 'Compare short-, medium-, and long-horizon consequences and path dependence.', 'stakeholder': 'Model affected parties, asymmetric information, incentives, and distributional effects.', 'ethical': 'Surface rights, duties, harms, fairness, reversibility, and value conflicts.', 'dual_process': 'Contrast the fast intuitive judgment with slower deliberate analysis.', 'argumentative': 'Steelman competing views, seek contrary evidence, and synthesize disagreements.', 'reference_class': 'Use outside-view base rates and adjust only for demonstrably relevant differences.', 'premortem': 'Assume the plan failed and work backward to causes, warnings, and mitigations.', 'consider_opposite': 'State the opposite hypothesis and identify evidence that would support it.', 'satisficing': 'Respect time, information, and search costs; define what is good enough.', 'calibration': 'Match confidence to evidence quality and specify what would change the conclusion.'}
